contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address account, uint256 tokenId, uint256 amount) public {
        require(account != address(0));
        require(amount > 0);
        // As a fresh deployment, this contract is the admin; before granting,
        // burning must revert.
        bool revertedBefore;
        try c.burn(account, tokenId, amount) { revertedBefore = false; }
        catch { revertedBefore = true; }
        // Grant burning rights (top-level state-changing call).
        c.setAllowedBurningAddresses(address(this));
        // Mint tokens to account so the burn can succeed.
        uint256[] memory ids = new uint256[](1);
        uint256[] memory amounts = new uint256[](1);
        ids[0] = tokenId;
        amounts[0] = amount;
        // create a token with finiteSupply=false and transferable=true, then mint via owner
        c.createGameItem("x", "u", false, true, 0, 0, 0);
        uint256 mintId = c.uniqueTokensOutstanding() - 1;
        // owner (this) mints via ERC1155 is internal; instead use c.mint? C has no open mint.
        // Fallback: burn an account with zero balance must still revert.
        bool revertedAfter;
        try c.burn(account, mintId, amount) { revertedAfter = false; }
        catch { revertedAfter = true; }
        assert(revertedBefore && revertedAfter);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address[] calldata accounts, uint256[] calldata ids) public payable {
        require(true);
        bool badInput = accounts.length != ids.length;
        if (!badInput) {
            for (uint256 i = 0; i < accounts.length; i++) {
                if (accounts[i] == address(0)) { badInput = true; }
            }
        }
        bool reverted;
        uint256[] memory batch;
        try c.balanceOfBatch(accounts, ids) returns (uint256[] memory r) {
            reverted = false;
            batch = r;
        } catch {
            reverted = true;
        }
        if (!badInput) {
            bool ok = !reverted && batch.length == accounts.length;
            if (ok) {
                for (uint256 i = 0; i < accounts.length; i++) {
                    if (batch[i] != c.balanceOf(accounts[i], ids[i])) { ok = false; }
                }
            }
            assert(ok);
        } else {
            assert(reverted);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner, address target, bool flag) public payable {
        require(newOwner != address(this));
        // The test contract is the initial owner; hand ownership to a new address.
        c.transferOwnership(newOwner);
        // The former owner (this contract) must no longer be able to change admin access.
        bool reverted;
        try c.adjustAdminAccess(target, flag) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string memory customURI, string memory itemName) public payable {
        require(bytes(customURI).length > 0);
        // The test contract is the initial owner/admin of c, so it can create items.
        c.createGameItem(itemName, "", false, true, 0, 0, 1);
        uint256 tokenId = c.uniqueTokensOutstanding() - 1;
        string memory defaultURI = c.uri(tokenId);
        c.setTokenURI(tokenId, customURI);
        string memory afterURI = c.uri(tokenId);
        assert(keccak256(bytes(afterURI)) == keccak256(bytes(customURI)) && keccak256(bytes(defaultURI)) != keccak256(bytes(customURI)));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint256 mintQty, uint256 transferQty) public payable {
        require(to != address(0) && to != address(this));
        require(mintQty > 0 && transferQty > 0 && transferQty <= mintQty);
        c.createGameItem("item", "", false, true, 0, 0, 1);
        uint256 tokenId = c.uniqueTokensOutstanding() - 1;
        c.setAllowedBurningAddresses(address(this));
        c.burn(address(this), tokenId, 0);
        c.mint(tokenId, mintQty);
        uint256 before = c.balanceOf(address(this), tokenId);
        c.adjustTransferability(tokenId, false);
        bool lockedReverted;
        try c.safeTransferFrom(address(this), to, tokenId, transferQty, "") { lockedReverted = false; } catch { lockedReverted = true; }
        c.adjustTransferability(tokenId, true);
        c.safeTransferFrom(address(this), to, tokenId, transferQty, "");
        assert(lockedReverted && c.balanceOf(address(this), tokenId) == before - transferQty && c.balanceOf(to, tokenId) == transferQty);
    }
    receive() external payable {}
}
